@pytest.mark.parametrize(("value", "expected"), SOURCE_MODEL_BOUNDARY_VECTORS)
def test_pinned_reference_model_boundary_vectors(value, expected):
    assert fixed_point_reference(value).result_register == expected


def test_source_vectors_are_ordered_and_include_required_edges():
    inputs = tuple(value for value, _ in SOURCE_MODEL_BOUNDARY_VECTORS)
    assert inputs == tuple(sorted(set(inputs)))
    assert {1, 2, 3, 4, 5, 6, 7, 8, 3_133_451, 3_133_452} <= set(inputs)
    assert 2_588_411 in inputs
    assert REFERENCE_SOURCE_COMMIT == "6ac78ec5ace6dfd5831ccac2547041408f5d8278"
    assert REFERENCE_SOURCE_SHA256 == (
        "bb90330dcf774f7b502de471293facba67f27952cc8808fe4a9970a9b1322e23"
    )
    assert LOCAL_REFERENCE_SOURCE.endswith(
        "verifiers/invsqrt/nr_reference_circuit.py"
    )
    assert LOCAL_REFERENCE_SOURCE_SHA256 == REFERENCE_SOURCE_SHA256


def test_output_is_independent_of_input_evaluation_order():
    values = (1, 3, 5, 6, 8, 12, 1_024, 2_588_411, 3_133_452)
    ascending = {
        value: fixed_point_reference(value).result_register
        for value in values
    }
    descending = {
        value: fixed_point_reference(value).result_register
        for value in reversed(values)
    }
    assert ascending == descending
